#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>
using namespace std;

constexpr int MOD = 1000000007;
constexpr int MMAX = 20;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    cin >> n >> s;

    n = min(n, static_cast<int>(s.size()));

    vector<unordered_map<int, int>> dp(n + 1);
    for (int i = 0; i <= n; ++i)
        dp[i][0] = 1;

    for (int i = 0; i < n; ++i) {
        for (const auto &[mask, ways] : dp[i]) {
            int value = 0;

            for (int j = i + 1; j <= n; ++j) {
                value = value * 2 + (s[j - 1] - '0');

                if (value == 0)
                    continue;
                if (value > MMAX)
                    break;

                int newMask = mask | (1 << (value - 1));
                int &current = dp[j][newMask];
                current += ways;
                if (current >= MOD)
                    current -= MOD;
            }
        }
    }

    int result = 0;
    for (int i = 0; i <= n; ++i) {
        for (int j = 1; j <= MMAX; ++j) {
            auto it = dp[i].find((1 << j) - 1);
            if (it != dp[i].end()) {
                result += it->second;
                if (result >= MOD)
                    result -= MOD;
            }
        }
    }

    cout << result;
    return 0;
}

