#include <iostream>
#include <algorithm>
using namespace std;

#define MOD 1000000007
#define MAX_MASK (1 << 20)

char s[77];
int nr[77][MAX_MASK];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, res = 0;
    constexpr int mmax = 20;

    cin >> n >> s;

    for (int i = 0; i <= n; ++i)
        nr[i][0] = 1;

    for (int i = 0; i < n; ++i) {
        const int maskLimit = 1 << min(i, mmax);

        for (int bitmask = 0; bitmask < maskLimit; ++bitmask) {
            if (nr[i][bitmask] == 0)
                continue;

            int val = 0;

            for (int j = i + 1; j <= n; ++j) {
                val = (val << 1) + (s[j - 1] - '0');

                if (val == 0)
                    continue;
                if (val > mmax)
                    break;

                int nextMask = bitmask | (1 << (val - 1));
                nr[j][nextMask] =
                    (nr[j][nextMask] + nr[i][bitmask]) % MOD;
            }
        }
    }

    for (int i = 0; i <= n; ++i)
        for (int j = 1; j <= mmax; ++j)
            res = (res + nr[i][(1 << j) - 1]) % MOD;

    cout << res;
    return 0;
}

